-- Replace old templates with comprehensive template library
-- Each template has detailed section guidelines stored in structure JSONB

DELETE FROM public.prd_templates WHERE is_built_in = true;

INSERT INTO public.prd_templates (workspace_id, name, description, category, structure, use_count, is_built_in) VALUES

-- ══════════════════════════
-- PRODUCT (4)
-- ══════════════════════════
(NULL, 'Peter''s PRD', 'Concise PRD with evidence-driven problem statements, measurable goals, and phased launch planning.', 'product',
 '{"sections":[{"name":"Team","guidelines":"List people involved with roles (PM, Design, Engineering, Analytics, Marketing) in a table."},{"name":"Problem","guidelines":"Describe customer problem with concrete evidence. Include specific customer segment, what they struggle with, and data/research."},{"name":"Goals","guidelines":"Define one output goal with 2-3 input metrics. Specify metric name, target % change, and timeframe. Include non-goals."},{"name":"Requirements","guidelines":"Write user stories with P0 (must ship) and P1 (should ship) priorities. Include high-level solution and milestones."},{"name":"Launch Plan","guidelines":"Define experiment design with success criteria, phased rollout percentages, monitoring duration, and rollback criteria."}]}',
 0, true),

(NULL, 'Aakash''s PRD', 'Comprehensive 14-section PRD with impact sizing, key flows, and detailed launch planning for team alignment.', 'product',
 '{"sections":[{"name":"Problem","guidelines":"State problem as testable hypothesis in 1-2 sentences with customer pain and business opportunity."},{"name":"High Level Approach","guidelines":"Describe approach without over-constraining design. Few sentences max."},{"name":"Narrative","guidelines":"Include common use case, edge case, and before/after scenarios to create empathy."},{"name":"Goals","guidelines":"Include measurable goals with baseline/target metrics and immeasurable goals about experience."},{"name":"Metrics","guidelines":"Define north star metric, 2-3 secondary metrics, and guardrail metrics with thresholds."},{"name":"Impact Sizing Model","guidelines":"Show step-by-step calculations with assumptions and revenue impact estimate."},{"name":"Non-goals","guidelines":"Explicitly state what you are NOT doing and why to prevent scope creep."},{"name":"Solution Alignment","guidelines":"Define in/out scope and list open questions for design/engineering exploration."},{"name":"Key Features","guidelines":"List features in priority order with P0/P1/P2, size estimate (S/M/L), and description."},{"name":"Future Considerations","guidelines":"Features saved for later that inform current decisions."},{"name":"Key Flows","guidelines":"Walk through every click and state including empty, loading, and error states."},{"name":"Key Logic","guidelines":"State business rules clearly with conditions, concrete examples, and edge cases."},{"name":"Launch Plan","guidelines":"Define phases with entry/exit criteria, experiment design, and risks/dependencies."},{"name":"Key Milestones","guidelines":"Milestone table with dates, owners, status, and dependencies."}]}',
 0, true),

(NULL, 'Lenny''s 1-Pager', 'Concise 1-page template for products with testable hypotheses, evidence, and solution clarity.', 'product',
 '{"sections":[{"name":"Description","guidelines":"2-3 sentences max. A stranger should understand the product. No jargon."},{"name":"Problem","guidelines":"Single sentence testable hypothesis focused on specific problem. Solution-agnostic."},{"name":"Why","guidelines":"Back up hypothesis with 3-5 data points. Include devil''s advocate section questioning evidence."},{"name":"Success","guidelines":"Define specific, measurable success metric with % change target."},{"name":"Audience","guidelines":"Specify user segment, platform, geography, and size. Explain why focus here first."},{"name":"What","guidelines":"Describe what users experience, not internal architecture. Walk through core experience."},{"name":"How","guidelines":"Specify approach (Build/Experiment/Prototype). Include technical considerations and risks."},{"name":"When","guidelines":"Timeline with milestones and confidence level."}]}',
 0, true),

(NULL, 'Product Brief for AI', 'Structured brief optimized for AI coding tools with 12 sections for direct implementation.', 'product',
 '{"sections":[{"name":"tl;dr","guidelines":"2-3 sentence summary with problem, core benefits, key features, and target audience."},{"name":"Goals","guidelines":"3-5 business goals with metrics, 3-5 user goals, and 2-3 non-goals."},{"name":"User Stories","guidelines":"Personas with stories in format: As [USER], I want [ACTION], so that [BENEFIT]."},{"name":"Functional Requirements","guidelines":"Group features by area and priority (P0/P1/P2). Be specific about behavior."},{"name":"User Experience","guidelines":"Entry point, first-time experience, core experience with step-by-step UI flows."},{"name":"Narrative","guidelines":"200-300 word user-centric story showing challenge, product solution, and positive outcome."},{"name":"Success Metrics","guidelines":"User metrics (DAU, completion, NPS), business metrics (revenue, conversion), technical metrics."},{"name":"Technical Considerations","guidelines":"Constraints, performance requirements, integration needs, architecture decisions."},{"name":"UI Architecture","guidelines":"Framework, component library, styling, state management, animations, accessibility."},{"name":"API & Backend","guidelines":"Framework, database, ORM, authentication, hosting, main endpoints."},{"name":"Performance & Scalability","guidelines":"Performance targets, scalability approach, accessibility requirements (WCAG)."},{"name":"Integration Points","guidelines":"Third-party services with purpose, SDK/library, configuration needed."}]}',
 0, true),

