-- TECHNICAL (8)
-- ══════════════════════════
(NULL, 'Feature Implementation Spec', 'Single-feature spec with exact acceptance criteria, edge cases, files to touch, and test plans.', 'technical',
 '{"sections":[{"name":"Feature Summary","guidelines":"1-2 sentences: what, why, who. Define in/out scope, prerequisites, dependencies."},{"name":"Acceptance Criteria","guidelines":"Numbered list split into Must-Have (P0), Should-Have (P1), Nice-to-Have (P2)."},{"name":"User Flow","guidelines":"Step-by-step happy path with alternate paths and specific UI components."},{"name":"Edge Cases & Error States","guidelines":"Input validation, system errors, permissions, empty states, rate limiting."},{"name":"Technical Approach","guidelines":"Files to create/modify with paths. Data flow from UI to database and back."},{"name":"Dependencies & Risks","guidelines":"Upstream/downstream dependencies, performance/security risks, rollback strategy."},{"name":"Test Plan","guidelines":"Manual testing checklist, unit/integration/E2E tests, regression checks."}]}',
 0, true),

(NULL, 'Technical Design Document', 'Architecture, data model, APIs, testing, deployment, security, and performance for engineers.', 'technical',
 '{"sections":[{"name":"Product Overview","guidelines":"Problem solved, user scenarios, benefits, KPIs, short-term vs long-term impact."},{"name":"Architecture","guidelines":"How components connect: frontend, backend, database, external services. Communication protocols and patterns."},{"name":"Data Model","guidelines":"Core entities with fields and types. Relationships, storage technology, caching strategy."},{"name":"Testing Plan","guidelines":"Unit, integration, E2E, performance tests. CI integration and code coverage targets."},{"name":"Deployment Plan","guidelines":"Environment setup, CI/CD pipeline, preview deployments, rollback strategy."},{"name":"Security & Performance","guidelines":"Auth, input validation, secrets management. Performance targets, optimization, monitoring."}]}',
 0, true),

(NULL, 'App Architecture Plan', 'Plan your system architecture before you start building. Covers data model, API design, auth, integrations, and deployment — everything an AI coding agent needs to scaffold your app correctly from the start.', 'technical',
 '{"sections":[{"name":"System Overview","guidelines":"What app does, who it is for, architecture type (monolith/microservices/serverless)."},{"name":"Data Model","guidelines":"Every core entity with fields and types. Relationships, indexes, unique constraints."},{"name":"API Design","guidelines":"API routes grouped by resource with METHOD, auth, request body, response format."},{"name":"Auth & Permissions","guidelines":"Auth provider, methods, roles, enforcement strategy, multi-tenancy approach."},{"name":"Third-Party Services","guidelines":"Each service: name, purpose, SDK, config (env vars), failure handling."},{"name":"Frontend Architecture","guidelines":"Framework, component library, styling, state management, pages with paths."},{"name":"Infrastructure & Deployment","guidelines":"Hosting, CI/CD pipeline, environment configs, required environment variables."}]}',
 0, true),

(NULL, 'Database Schema Design', 'Database design with entities, relationships, indexes, access patterns, migrations, and security.', 'technical',
 '{"sections":[{"name":"Overview & Goals","guidelines":"Database technology, hosting, rationale. Design priorities: read/write heavy, normalization, scale."},{"name":"Core Entities","guidelines":"All tables with fields, types, constraints. Mark PK, FK, UQ, IDX, nullable."},{"name":"Relationships & Constraints","guidelines":"All relationships with FK behavior (CASCADE, SET NULL, RESTRICT). Business rules."},{"name":"Indexes & Performance","guidelines":"Required indexes with type and supported query. N+1 risks, pagination, caching."},{"name":"Access Patterns","guidelines":"Most common queries with SQL, frequency, indexes used."},{"name":"Migration Plan","guidelines":"Migration tool, workflow, seed data strategy, zero-downtime approach."},{"name":"Security & Privacy","guidelines":"Sensitive data, encryption, compliance (GDPR, CCPA), data retention policies."}]}',
 0, true),

(NULL, 'API Documentation', 'This template provides a comprehensive guide for documenting APIs, including purpose, functionalities, architecture, authentication, error handling, and endpoints.', 'technical',
 '{"sections":[{"name":"API Overview","guidelines":"What API does, style (REST/GraphQL), base URL, versioning, rate limiting, data format."},{"name":"Authentication","guidelines":"Setup steps, usage in requests, curl examples for each auth method."},{"name":"Endpoints","guidelines":"For each: METHOD /path, description, auth, parameters, request/response body, errors."},{"name":"Error Handling","guidelines":"Error response format, error code reference, retry strategy."},{"name":"Code Examples","guidelines":"Working examples in cURL, JavaScript/TypeScript, and Python."},{"name":"Webhooks & Events","guidelines":"Available events, payload format, signature verification, retry policy."},{"name":"SDKs, Rate Limits & Support","guidelines":"Official SDKs, rate limit tiers, status page, changelog URLs."}]}',
 0, true),

(NULL, 'AI Coding Rules & Standards', 'Define the conventions, patterns, and rules for AI coding assistants working on your codebase. Generates a comprehensive rules file (like CLAUDE.md or .cursorrules) that keeps AI output consistent with your project.', 'technical',
 '{"sections":[{"name":"Project Overview","guidelines":"Project description, maturity level, key technologies, repository structure."},{"name":"Tech Stack & Conventions","guidelines":"Every major technology with version and project-specific conventions."},{"name":"Code Style Rules","guidelines":"Naming conventions, import order, export preferences, TypeScript strictness, formatting."},{"name":"Component & Architecture Patterns","guidelines":"Component structure, data fetching, state management, API route patterns."},{"name":"Do''s and Don''ts","guidelines":"Explicit rules with concrete examples. Cover React, TypeScript, styling, architecture."},{"name":"Testing & Quality","guidelines":"Testing frameworks, test file naming, what to test, linting/formatting config."},{"name":"Common Pitfalls","guidelines":"Deprecated patterns, environment quirks, files needing extra care, known bugs."}]}',
 0, true),

(NULL, 'Refactoring Plan', 'Engineering plan for codebase refactoring with problem analysis, target state, and migration strategy.', 'technical',
 '{"sections":[{"name":"Current State","guidelines":"For each problem: module/file, what is wrong (specific), impact (build time, errors, confusion)."},{"name":"Target State","guidelines":"New patterns with before/after examples. Objectively verifiable completion criteria."},{"name":"Motivation & Urgency","guidelines":"Why now: blocked feature, scaling issue, recurring incidents. Cost of not refactoring."},{"name":"Scope & Boundaries","guidelines":"What IS and IS NOT being changed. Break into phases if independent."},{"name":"Migration Strategy","guidelines":"Approach: strangler fig, big bang, or incremental. How old/new coexist."},{"name":"Implementation Steps","guidelines":"Ordered steps, each leaving codebase deployable. Files changed, PR size."},{"name":"Risk Assessment & Rollback","guidelines":"For each risk: likelihood, impact, mitigation, rollback. Point of no return."}]}',
 0, true),

(NULL, 'Spec for AI Prototyping', 'Self-contained spec for AI prototyping tools (v0, Bolt, Lovable) with design, tech stack, and flows.', 'technical',
 '{"sections":[{"name":"Product Overview","guidelines":"Core concept, who it is for, primary user action. Scope for prototype vs later."},{"name":"Design & Visual Style","guidelines":"Component library, color scheme (hex codes), theme, typography, reference sites."},{"name":"Tech Stack","guidelines":"Framework, language, database, ORM, auth, hosting, key libraries."},{"name":"Pages & Navigation","guidelines":"Every page with URL path, purpose, navigation structure, auth requirements."},{"name":"Core User Flows","guidelines":"2-4 most important interactions step-by-step with first win moment."},{"name":"Data Model & Backend","guidelines":"Core entities with fields. API endpoints, data persistence, background jobs."},{"name":"Key Components","guidelines":"UI components needing special attention with behavior and library preferences."},{"name":"AI Generation Notes","guidelines":"Features to skip/stub, performance considerations, patterns to follow/avoid."}]}',
