(NULL, 'Go-to-Market Plan', 'Strategic plan for product launch with market analysis, positioning, pricing, and success metrics.', 'marketing',
 '{"sections":[{"name":"Executive Summary","guidelines":"One paragraph covering what, who, when, how, and 90-day goal."},{"name":"Market Analysis","guidelines":"TAM/SAM/SOM with sources. Target segments, competitive landscape, differentiation."},{"name":"Product Positioning","guidelines":"Positioning statement: For [customer] who [need], [product] is [category] that [benefit]."},{"name":"Pricing Strategy","guidelines":"Model type, tiers with inclusions, price points with justification, competitive context."},{"name":"Promotional Plan","guidelines":"For each channel: tactic, timeline, owner, budget. Content plan and PR opportunities."},{"name":"Sales Strategy","guidelines":"Sales motion (self-serve, sales-assisted, outbound). Sales enablement materials."},{"name":"Success Metrics","guidelines":"30-day targets (awareness, activation) and 90-day targets (retention, growth)."}]}',
 0, true),

(NULL, 'Landing Page Brief', 'Creative brief for landing page with hero, value props, social proof, features, CTAs, and design.', 'marketing',
 '{"sections":[{"name":"Page Goal & Audience","guidelines":"Single primary conversion action. Traffic source, awareness level, key objection."},{"name":"Hero Section","guidelines":"Headline (8 words), subheadline (1-2 sentences), CTA button text, hero visual."},{"name":"Value Propositions","guidelines":"3-4 key benefits with headline, description, and visual suggestion."},{"name":"Social Proof","guidelines":"Testimonials, logo bar, usage stats, press mentions, case study snippet."},{"name":"Feature Showcase","guidelines":"3-5 features with benefit-oriented headline and 2-3 sentence description."},{"name":"CTA & Conversion","guidelines":"Primary CTA with button text, form fields, secondary CTA, trust builders."},{"name":"Design Direction","guidelines":"Color palette, typography, spacing, vibe, reference sites, mobile adaptations."}]}',
 0, true),

(NULL, 'PR FAQ', 'Amazon-style press release and FAQs announcing product launch from customer perspective.', 'marketing',
 '{"sections":[{"name":"Heading","guidelines":"Product name that target customer understands. One-sentence tagline."},{"name":"Subheading","guidelines":"Format: [Product] helps [customer] [achieve benefit]. Benefit-focused."},{"name":"Summary Paragraph","guidelines":"Press release lead with city, date, company, product, key benefit. 3-4 sentences."},{"name":"Problem Paragraph","guidelines":"Entirely from customer perspective. Quantify problem. DO NOT mention product."},{"name":"Solution Paragraph(s)","guidelines":"Lead with outcome. Explain in plain language. Highlight 2-3 key capabilities."},{"name":"Quotes & Getting Started","guidelines":"Company spokesperson quote, customer quote with real use case, how to start."},{"name":"External FAQs","guidelines":"Q&A for customers/journalists: pricing, differentiation, availability, security."},{"name":"Internal FAQs","guidelines":"Q&A for leadership: why now, revenue impact, build cost, risks, strategy fit."}]}',
 0, true),

(NULL, 'Release Notes', 'Template for documenting software release updates with features, improvements, and bug fixes.', 'marketing',
 '{"sections":[{"name":"Release Information","guidelines":"Product name, version (X.Y.Z), release date, release type, one-paragraph summary."},{"name":"New Features","guidelines":"For each: name, 1-2 sentence description, screenshot/GIF if visual. Note if beta."},{"name":"Improvements","guidelines":"Format: [Area]: [What improved and why it matters]. Specific numbers."},{"name":"Bug Fixes","guidelines":"Format: Fixed issue where [action] would [broken behavior]. Group by area."},{"name":"Known Issues","guidelines":"Issue description, impact, workaround, status (Investigating/In progress/Planned)."},{"name":"Breaking Changes & Migration","guidelines":"What changed, before/after behavior, action required, deadline."}]}',
 0, true),

(NULL, 'Product Launch Checklist', 'Comprehensive launch checklist organized chronologically from T-4 weeks to post-launch.', 'marketing',
