 0, true),

(NULL, 'Customer Journey Map', 'Map customer experience across journey stages with pain points, moments of truth, and action plan.', 'research',
 '{"sections":[{"name":"Customer Persona","guidelines":"Demographics, behavior, needs/goals, challenges, preferred channels."},{"name":"Journey Stages","guidelines":"Map six stages: Awareness, Consideration, Decision, Onboarding, Retention, Advocacy."},{"name":"Pain Points & Moments of Truth","guidelines":"For each: stage, what goes wrong, severity, frequency, evidence."},{"name":"Opportunities for Improvement","guidelines":"Unmet needs, experience gaps, innovation areas, quick wins."},{"name":"Action Plan","guidelines":"Initiatives by urgency: Immediate, Near-term, Long-term with owner and effort."}]}',
 0, true),

(NULL, 'User Testing Plan', 'Usability testing plan with objectives, participants, scenarios, metrics, and decision framework.', 'research',
 '{"sections":[{"name":"Test Objectives","guidelines":"Primary questions to learn. Success criteria: completion rate, time, error rate, satisfaction."},{"name":"Participant Criteria","guidelines":"5-8 participants per segment. Target profile, exclusions, screening questions, incentive."},{"name":"Test Scenarios","guidelines":"Realistic scenarios without UI hints. One easy and one challenging scenario."},{"name":"Tasks","guidelines":"For each: what to accomplish, starting point, success criteria, time limit."},{"name":"Metrics for Success","guidelines":"Quantitative: completion %, time, errors, SUS. Qualitative: observations, mental model."},{"name":"Feedback Collection","guidelines":"During: think-aloud, recording, notes. Post: questionnaire, debrief interview."},{"name":"Analysis & Recommendations","guidelines":"Rate findings by severity/frequency. Prioritized recommendations with decision framework."}]}',
 0, true),

