(NULL, 'OKRs', 'Structured OKR template with objectives, key results, initiatives, alignment, and scoring.', 'planning',
 '{"sections":[{"name":"Objective","guidelines":"Qualitative, ambitious but achievable, time-bound, aligned to company strategy."},{"name":"Key Results","guidelines":"Format: [Verb] [metric] from [baseline] to [target] by [date]. Mix leading and lagging."},{"name":"Initiatives","guidelines":"1-3 projects per KR with name, owner, and effort estimate (S/M/L/XL)."},{"name":"Alignment","guidelines":"Company objectives supported, cross-team dependencies, strategic context."},{"name":"Key Stakeholders","guidelines":"Table: Role, Person, Responsibility. Escalation path for trade-offs."},{"name":"Timeline & Checkpoints","guidelines":"Week 2, Month 1, Mid-quarter, End of quarter milestones and review cadence."},{"name":"Risks and Mitigations","guidelines":"For each: what could go wrong, likelihood, which KRs affected, mitigation."},{"name":"Review & Scoring","guidelines":"Scoring 0.0-1.0 scale. Review process and retrospective questions."}]}',
 0, true),

(NULL, 'Founding Hypothesis', 'Jake Knapp framework: customer, problem, approach, competitors, and differentiation.', 'planning',
 '{"sections":[{"name":"Customer Identification","guidelines":"Be specific: not ''businesses'' but ''B2B SaaS companies with 10-50 employees''. Validate with research."},{"name":"Problem Definition","guidelines":"From customer perspective. Quantify pain. Distinguish root problem from symptoms."},{"name":"Solution Approach","guidelines":"Describe approach, not every feature. Why THIS approach vs alternatives considered."},{"name":"Competitive Analysis","guidelines":"For each competitor: name, strengths, weaknesses, why customers switch."},{"name":"Differentiation Strategy","guidelines":"Type: Experience/Speed/Price/Integration/Technology. Complete hypothesis statement."}]}',
 0, true),

(NULL, 'Product Strategy Document', 'Strategy covering vision, market analysis, OKRs, product strategies, roadmap, and risks.', 'planning',
 '{"sections":[{"name":"Product Vision & Mission","guidelines":"Vision: ambitious, stable over years. Mission: who you serve, value delivered, unique positioning."},{"name":"Market Analysis","guidelines":"3-5 industry trends. Competitor analysis. Target segments. TAM/SAM/SOM with sources."},{"name":"Objectives & Key Results","guidelines":"Ambitious time-bound objectives with 2-4 measurable KRs each. Company alignment."},{"name":"Product Strategies","guidelines":"Product development, marketing/sales, customer success strategies."},{"name":"Product Roadmap","guidelines":"Near-term, medium-term, long-term initiatives with goals and sequencing rationale."},{"name":"Risks & Success Criteria","guidelines":"Risks with likelihood/impact/mitigation. Success criteria at 3/6/12 months."}]}',
 0, true),

(NULL, 'Release Plan', 'Guide for planning product release with objectives, scope, stakeholders, timeline, and risks.', 'planning',
 '{"sections":[{"name":"Product Overview","guidelines":"Product/feature name, target audience, value proposition, release type."},{"name":"Release Objectives","guidelines":"Specific measurable outcomes with metric and target. Relevance to KPIs."},{"name":"Release Scope","guidelines":"Included features with priority, bug fixes, deferred items. Non-functional requirements."},{"name":"Stakeholders & RACI","guidelines":"RACI matrix mapping activities to Responsible/Accountable/Consulted/Informed."},{"name":"Release Timeline & Milestones","guidelines":"Milestone table with dates, owners, status. Deploy strategy and rollback."},{"name":"Risk Assessment","guidelines":"Risk matrix with likelihood, impact, mitigation, owner. Go/no-go criteria."},{"name":"Measurement & Success Criteria","guidelines":"Day-1, Week-1, Month-1 metrics. Post-release review format."}]}',
 0, true),

-- ══════════════════════════
-- QUALITY (3)
-- ══════════════════════════
(NULL, 'Bug Investigation & Fix Plan', 'Structured document for investigating, diagnosing, and fixing a bug. Covers symptoms, reproduction, root cause analysis, proposed fix, and verification — useful for complex bugs that need clear documentation.', 'quality',
 '{"sections":[{"name":"Bug Summary","guidelines":"Broken behavior in 1-2 sentences. Severity, affected users, first observed, business impact."},{"name":"Reproduction Steps","guidelines":"Exact numbered steps from clean state. Environment details, frequency, time-dependent factors."},{"name":"Expected vs. Actual Behavior","guidelines":"What SHOULD happen vs what ACTUALLY happens. Console errors, network issues."},{"name":"Root Cause Analysis","guidelines":"Investigation trail. Exact file path and function. Code path from user action to failure."},{"name":"Proposed Fix","guidelines":"Files to modify, changes needed. Why this addresses root cause. Alternative approaches."},{"name":"Test Plan","guidelines":"Manual verification, edge case checks, unit/integration/E2E tests to write."},{"name":"Prevention","guidelines":"Immediate actions: test coverage, validation. Systemic: type safety, architecture."}]}',
 0, true),

(NULL, 'Accessibility Compliance Checklist', 'A comprehensive checklist to ensure accessibility compliance in design, content readability, and navigation for all users, including those with disabilities.', 'quality',
 '{"sections":[{"name":"Accessibility Overview","guidelines":"Target standard, legal requirements, scope, tools (axe, Lighthouse, screen readers)."},{"name":"Perceivable","guidelines":"Alt text, captions, color contrast (4.5:1), responsive at 200% zoom."},{"name":"Operable","guidelines":"Keyboard navigation, logical tab order, skip-to-content, 44x44px touch targets."},{"name":"Understandable","guidelines":"Lang attribute, visible labels, specific error messages, confirmation for destructive actions."},{"name":"Robust","guidelines":"Semantic HTML, proper ARIA, screen reader testing (VoiceOver, NVDA, TalkBack)."},{"name":"Findings & Remediation Plan","guidelines":"Issues by severity with fix-by dates. Process improvements for ongoing compliance."}]}',
 0, true),

(NULL, 'Product Security Assessment', 'Security evaluation covering architecture, data security, auth, threats, and incident response.', 'quality',
 '{"sections":[{"name":"Product Overview","guidelines":"Functionality, target users, attack vectors. Tech stack, infrastructure, dependencies."},{"name":"Data Security","guidelines":"Data classification (Critical/Sensitive/Internal/Public). Encryption, hashing, compliance."},{"name":"Authentication & Authorization","guidelines":"Auth methods, session management, password policy, RBAC/ABAC, API security."},{"name":"Threat Analysis & Risk Assessment","guidelines":"For each threat: description, vector, likelihood, impact, current controls."},{"name":"Security Controls & Monitoring","guidelines":"Preventive: validation, CSP, CORS. Detective: logging, alerting, vulnerability scanning."},{"name":"Incident Response & Business Continuity","guidelines":"Detection, triage, containment, communication, recovery, post-mortem. Backup strategy."}]}',
 0, true),

